// seed: tests/seed.user1.spec.ts
import { test, expect } from '@playwright/test';
import * as path from 'path';

test.use({ storageState: path.resolve(__dirname, '../../../auth/user1.json') });

test.describe('Главная', () => {
  test('HM-03 Окно времени под датой (вверху слева); тег важной даты еврейский #6a86f7e5 @prod-safe', async ({ page }) => {
    // 1. Открыть `/home`: `getBoundingClientRect` еврейской даты, окна времени и строки «נוסח …».
    await page.goto('/home');
    await expect(page.getByRole('button', { name: 'התחל תפילה' })).toBeVisible({ timeout: 20_000 });
    const dateEl = page.getByText(/^[א-ת״׳' ]+ תשפ״ז$/).first();
    const windowEl = page.getByText(/^\d{2}:\d{2} - \d{2}:\d{2}$/).first();
    const nusachEl = page.getByText(/^נוסח /).first();
    await expect(dateEl).toBeVisible();
    await expect(windowEl).toBeVisible();
    await expect(nusachEl).toBeVisible();
    const d = (await dateEl.boundingBox())!;
    const w = (await windowEl.boundingBox())!;
    const n = (await nusachEl.boundingBox())!;
    const vw = page.viewportSize()!.width;
    // Окно времени под датой, в левой части экрана, выше строки «נוסח …».
    expect(w.y).toBeGreaterThan(d.y);
    expect(w.y).toBeLessThan(n.y);
    expect(w.x + w.width / 2).toBeLessThan(vw / 2);

    // 2. Блок «תאריכים חשובים»: прочитать тег карточки и вторичную строку.
    await expect(page.getByText('תאריכים חשובים', { exact: true })).toBeVisible();
    // Тег — еврейский месяц и день (например «תשרי» / «י״ט»), григорианская дата — вторичной строкой.
    await expect(page.getByText('אייר', { exact: true }).first()).toBeVisible();
    await expect(page.getByText('ט׳', { exact: true }).first()).toBeVisible();
    await expect(page.getByText('30.04.2004', { exact: true })).toBeVisible();
  });
});
